class Stack(capacity):
  items = array of size capacity
  top = -1

  function push(x):
    if top == capacity - 1:
      raise StackOverflowError
    top = top + 1
    items[top] = x

  function pop():
    if top == -1:
      raise StackUnderflowError
    val = items[top]
    top = top - 1
    return val

  function peek():
    if top == -1:
      raise StackUnderflowError
    return items[top]
